{
  "source": "<!--<link rel="stylesheet" href="cmdsspp_enrollment_styles.css"/> -->
<link rel="stylesheet" href="cmdspp_enrollment_styles.css">
{% include 'cmdspp_Loader' %}
   {% include 'cmdspp_ToastModal' %}
<div class="cmdspp-enrollment-page">
    
    <!-- Enrollment -->
    <div class="cmdspp-enroll-page-title">{{ pageTitle }}</div>

    <!-- Container -->
    <div class="cmdspp-main-container">

        <!-- Heading 2 + Paragraph -->
        <div class="cmdspp-info-container">
            <div class="cmdspp-enroll-subtitle">
                {{ pageSubtitle }}
            </div>

            <div class="cmdspp-enroll-description">
                {{ pageDescription }}
            </div>
        </div>

        <!-- Container:margin -->
        <div class="cmdspp-grid-wrapper">
            <div id="cmdsppEnrollmentGrid"
                 class="cmdspp-enrollment-grid">
            </div>
        </div>

    </div>
    <div id="cmdspp-enroll-provider-modal"
     class="cmdspp-enroll-modal-overlay">

    <div class="cmdspp-enroll-modal">

        <div class="cmdspp-enroll-modal-header">
            <span>Provider Type</span>
            <span class="cmdspp-enroll-close">&times;</span>
        </div>

        <div class="cmdspp-enroll-modal-body">

            <div class="cmdspp-enroll-modal-description">
                Please select the provider type to continue
            </div>

            <label class="cmdspp-enroll-modal-label">
                Select Provider Type
            </label>

            <select id="cmdspp-enroll-provider-type"
                    class="cmdspp-enroll-provider-select">
                <option value="">Select</option>
                <option value="Hospital">Hospital</option>
                <option value="Clinic">Clinic</option>
                <option value="Physician">Physician</option>
                <option value="Laboratory">Laboratory</option>
            </select>

        </div>

        <div class="cmdspp-enroll-modal-footer">
            <button id="cmdspp-enroll-cancel-btn"
                    class="cmdspp-enroll-cancel-btn">
                Cancel
            </button>

            <button id="cmdspp-enroll-submit-btn"
                    class="cmdspp-enroll-submit-btn">
                Submit
            </button>
        </div>

    </div>

</div>
</div>

<script>
  // Safely embed the raw JSON string using the `json` filter (escapes quotes/HTML properly)
  var cmdsppRaw = {{ settings["cmdspp_ENV_Automate_Flow_Url"] | json }};
   var currentUserId = window.cmdsppUserId ;
   var currentEmailId = window.cmdsppEmailId ;
  // If the setting value comes through as a string, parse it; if Liquid already gave an object, use as-is
  var cmdsppUrls = typeof cmdsppRaw === "string" ? JSON.parse(cmdsppRaw) : cmdsppRaw;
  
  window.cmdsppConfig = {
    pageTitle: "{{ pageTitle }}",
    pageSubtitle: "{{ pageSubtitle }}",
    pageDescription: "{{ pageDescription }}",
    enrollmentApiUrl: cmdsppUrls?.cmdspp_Enrollmenttype,
    currentUserId: currentUserId,
    currentEmailId:currentEmailId
  };
</script>

<script>
    const cmdsppPageTitle = "{{ pageTitle }}";
const cmdsppPageSubtitle = "{{ pageSubtitle }}";
const cmdsppPageDescription = "{{ pageDescription }}";
const enrollmentApiUrl = window?.cmdsppConfig?.enrollmentApiUrl;
const UserId = window?.cmdsppConfig?.currentUserId;
const EmailId = window?.cmdsppConfig?.currentEmailId;


$(document).ready(function () {

    const cmdsppGrid = document.getElementById("cmdsppEnrollmentGrid");
showLoader("");
console.log("Enrollment API URL:", enrollmentApiUrl);
  fetch(enrollmentApiUrl, {
    method: "POST",
    headers: {
        "Accept": "application/json",
        "Content-Type": "application/json"
    },
    body: JSON.stringify({
    action: "GetEnrollmentTypes"
})
})
.then(response => {
    if (!response.ok) {
        throw new Error(`HTTP Error: ${response.status}`);
    }
    return response.json();
})
.then(result => {

    const cmdsppEnrollmentTypes = (result || []).sort(
        (a, b) => Number(a.code) - Number(b.code)
    );

    const cmdsppIconClasses = [
        "cmdspp-purple-bg",
        "cmdspp-red-bg",
        "cmdspp-blue-bg",
        "cmdspp-orange-bg",
        "cmdspp-green-bg",
        "cmdspp-cyan-bg"
    ];
    
    cmdsppGrid.innerHTML = cmdsppEnrollmentTypes.map((item, index) => {
    return `
        <div class="cmdspp-enrollment-card">
        <div class="cmdspp-card-tooltip"> ${item.tooltip || ''} </div>
           <div class="cmdspp-card-icon ${cmdsppIconClasses[index % cmdsppIconClasses.length]}">
           <img src="${window.location.origin}${item.Icon || ''}"
           alt="${item.title || ''}"
           class="cmdspp-enrollment-icon"/>
           </div>
            <div class="cmdspp-card-content">
                <div class="cmdspp-card-title">
                    ${item.title || ''}
                </div>
            
                <div class="cmdspp-card-description">
                    ${item.description || ''}
                </div>
                <div class="cmdspp-enroll-link ${!item?.status ? 'disabled' : ''}" 
                
                 data-id="${item.id || ''}"
                 data-enrollment="${item.title || ''}"
                 data-enrollment-guid="${item.enrollment_guid || ''}">
                 Enroll Now ›
            </div>

         </div>
        </div>
    `}).join('');
})
.catch(error => {
    console.error("Enrollment Type Load Error:", error);
    cmdsppShowToast("error", "Unable to load enrollment types. Please try again.");

})
.finally(() => {

hideLoader();

});

});
function callSafeAjax(url, method, data) {
    return new Promise(function (resolve, reject) {

        webapi.safeAjax({
            type: method,
            url: url,
            contentType: "application/json",
            data: data ? JSON.stringify(data) : null,

            success: function (response, textstatus, xhr) {
                if(method=="POST"){
                    var entityId = xhr.getResponseHeader("entityid");
                    resolve(entityId);
                }else{
                    resolve(response);

                }
            },

            error: function (xhr) {
                console.error("API Error:", xhr.responseText);
                reject(xhr);
            }
        });

    });
}

(function(webapi, $) {
    function safeAjax(ajaxOptions) {
        var deferredAjax = $.Deferred();
        shell.getTokenDeferred().done(function(token) {
            if (!token) {
                deferredAjax.rejectWith(this, [{
                    status: 403,
                    statusText: "No CSRF Token"
                }]);
                return;
            }
            if (!ajaxOptions.headers) {
                ajaxOptions.headers = {};
            }
            ajaxOptions.headers["__RequestVerificationToken"] = token;
            $.ajax(ajaxOptions)
                .done(function(data, textStatus, jqXHR) {
                    deferredAjax.resolveWith(this, [data, textStatus, jqXHR]);
                })
                .fail(function(jqXHR, textStatus, errorThrown) {
                    deferredAjax.rejectWith(this, [jqXHR, textStatus, errorThrown]);
                });
        }).fail(function() {
            deferredAjax.rejectWith(this, [{
                status: 403,
                statusText: "Token retrieval failed"
            }]);
        });
        return deferredAjax.promise();
    }
    webapi.safeAjax = safeAjax;
})(window.webapi = window.webapi || {}, jQuery);

$(document).on("click", ".cmdspp-enroll-link:not(.disabled)", function () {

    const enrollmentId = $(this).data("id");
    const enrollmentName = $(this).data("enrollment");
    // const enrollmentGuid = $(this).data("enrollment-guid");

    showLoader("");
    const providerTypesQuery = `/_api/cmdspp_pc_pvd_enrol_map_tbs?$filter=_cmdspp_p_enrol_fk_id_value eq ${enrollmentId} and statecode eq 0 &$select=cmdspp_p_pvd_fk_id &$expand=cmdspp_p_pvd_fk_id($select=cmdspp_p_pvd_typ_nam,cmdspp_pc_pvd_typ_tbid,cmdspp_p_pvd_typ)`;
    callSafeAjax(providerTypesQuery,'GET').then((availableProviders)=>{
        let usedProviderTypesQuery  = `/_api/cmdspp_p_dtl_tbs?$filter=_cmdspp_created_by_user_value eq ${UserId} and _cmdspp_p_provider_ty_lkpid_value ne null and cmdspp_p_appln_status ne 7 and statecode eq 0 
        &$select=cmdspp_p_dtl_tbid
        &$expand=cmdspp_p_provider_ty_lkpid($select=cmdspp_p_pvd_typ_nam,cmdspp_pc_pvd_typ_tbid)`;
        callSafeAjax(usedProviderTypesQuery,'GET').then((usedProviders)=>{
            const array1 = availableProviders.value;
            const array2 = usedProviders.value;
            const filteredProviders = array1.filter(a => {
                const providerTypeId =a.cmdspp_p_pvd_fk_id?.cmdspp_pc_pvd_typ_tbid;
                const match = array2.find(
                    b =>
                        b.cmdspp_p_provider_ty_lkpid?.cmdspp_pc_pvd_typ_tbid === providerTypeId
                );
                if (!match || match?.cmdspp_p_dtl_tbid == this.enrollmentInfo?.ApplicationId) {
                    return true;
                }
            });
            if (!filteredProviders || filteredProviders.length === 0) {
            // No provider types remaining — do not create an enrollment record
                cmdsppShowToast("error", "All provider types are in progress");
                hideLoader();
                return;
            }else{
                let saveEnrollQuery = "/_api/cmdspp_p_dtl_tbs";
                var payload = {
                    "cmdspp_p_enrolment_type": enrollmentName,
                    "cmdspp_created_by_user@odata.bin": `cmdspp_g_usr_dtls_tb/${UserId}`,
                    "cmdspp_p_appln_email": EmailId,
                    "cmdspp_p_first_nam":"Juan",
                    "cmdspp_p_last_nam":"NARVAEZ",

                }
                callSafeAjax(saveEnrollQuery,"POST",payload).then((savedataID)=>{
                    let recordId = savedataID
                    let fetchEnrollmentIdQuery = `/_api/cmdspp_p_dtl_tbs?$filter=cmdspp_p_dtl_tbid eq ${recordId} and statecode eq 0 
                    &$select=cmdspp_p_dtl_tbid,cmdspp_p_sys_id`;
                    callSafeAjax(fetchEnrollmentIdQuery,"GET").then((enrollmentResp)=>{
                        console.log(enrollmentResp)
                        let applicationNumber = enrollmentResp?.value?.[0]?.cmdspp_p_sys_id
                        let applicationId = enrollmentResp?.value?.[0]?.cmdspp_p_dtl_tbid
                        window.cmdsppEnrollId = applicationNumber ;
                        window.cmdsppApplicationId = applicationId ;
                        window.location.href="/Enrollment-pp/EnrollmentPC?id=" + encodeURIComponent(applicationNumber)+ "&record=" + encodeURIComponent(applicationId);
                    })
                })
            }

        })
    })

    
    // Step 1: Check provider availability BEFORE creating the enrollment record
    // fetch(enrollmentApiUrl, {
    //     method: "POST",
    //     headers: {
    //         "Accept": "application/json",
    //         "Content-Type": "application/json"
    //     },
    //     body: JSON.stringify({
    //         action: "GetProviderTypes",
    //         enrollmentGuid: enrollmentId,
    //         currentUserId: UserId
    //     })
    // })
    // .then(response => {
    //     if (!response.ok) {
    //         throw new Error(`HTTP Error: ${response.status}`);
    //     }
    //     return response.json();
    // })
    // .then(providerData => {

    //     if (!providerData || providerData.length === 0) {
    //         // No provider types remaining — do not create an enrollment record
    //         cmdsppShowToast("error", "All provider types are in progress");
    //         hideLoader();
    //         return;
    //     }

    //     // Step 2: Providers available — proceed to create the enrollment record
    //     return fetch(enrollmentApiUrl, {
    //         method: "POST",
    //         headers: {
    //             "Accept": "application/json",
    //             "Content-Type": "application/json"
    //         },
    //         body: JSON.stringify({
    //             enrollmentType: enrollmentName,
    //             UserId: UserId,
    //             EmailId: EmailId,
    //             action: "SetEnrollmentId"
    //         })
    //     })
    //     .then(response => {
    //         if (!response.ok) {
    //             throw new Error(`HTTP Error: ${response.status}`);
    //         }
    //         return response.json();
    //     })
    //     .then(result => {
    //         // Redirect with newly created record id
    //         window.location.href =
    //             "/Enrollment-pp/Enroll-Form?id=" +
    //             encodeURIComponent(result.applicationNumber);
    //     })
    //     .finally(() => {
    //         hideLoader();
    //     });
    // })
    // .catch(error => {
    //     console.error("Enrollment Creation Error:", error);
    //     cmdsppShowToast("error", "Unable to create enrollment record. Please try again.");
    //     hideLoader();
    // });

});
</script>"
}
